function DefaultSplits({group,name,onSave}:{group:Group;name:(id:string)=>string;onSave:(g:Group)=>void}){const [weights,setWeights]=useState<Record<string,number>>(group.defaults||Object.fromEntries(group.members.map(p=>[p,1])));return <div className="dialog-form"><p className="notice">Set relative shares for {group.name}. For a 60/40 split, enter 60 and 40. New expenses will use these ratios.</p>{group.members.map(p=><label className="split-person" key={p}><span>{name(p)}</span><input aria-label={name(p)+' shares'} type="number" min="0" value={weights[p]??0} onChange={e=>setWeights({...weights,[p]:Number(e.target.value)})}/></label>)}<button className="btn primary" onClick={()=>{if(Object.values(weights).some(v=>v<0||!Number.isFinite(v))||!Object.values(weights).some(v=>v>0))return toast.error('Use positive shares for at least one person.');onSave({...group,defaults:weights})}}>Save default split</button></div>}
